SELECT repo_name, COUNT(*) AS total, COUNT(message) AS nonnull, SUM(CASE WHEN length(message) < 1000 THEN 1 ELSE 0 END) AS under_1000, SUM(CASE WHEN message IS NOT NULL AND length(message) < 1000 AND lower(message) NOT LIKE 'merge%' AND lower(message) NOT LIKE 'update%' AND lower(message) NOT LIKE 'test%' THEN 1 ELSE 0 END) AS case_insensitive_ok, SUM(CASE WHEN message IS NOT NULL AND length(message) < 1000 AND message NOT LIKE 'merge%' AND message NOT LIKE 'update%' AND message NOT LIKE 'test%' THEN 1 ELSE 0 END) AS case_sensitive_ok FROM commits WHERE repo_name IN ('tensorflow/tensorflow','apple/swift') GROUP BY repo_name
